// Extract and validate booking data
const bookingData = $input.item.json.data;

if (!bookingData.booking_id || !bookingData.customer_id || !bookingData.property_id) {
  throw new Error('Missing required booking fields');
}

return {
  booking_id: bookingData.booking_id,
  customer_id: bookingData.customer_id,
  property_id: bookingData.property_id,
  date: bookingData.date,
  time: bookingData.time,
  tenant_id: bookingData.tenant_id || 'default'
};

// Generate calendar event
const booking = $input.item.json;
const property = $input.item.json;

const startTime = `${booking.date}T${booking.time}:00`;
const endTime = new Date(new Date(startTime).getTime() + 60 * 60 * 1000).toISOString(); // 1 hour visit

const calendarEvent = {
  summary: `Property Visit - ${booking.property_id}`,
  description: `Property visit for customer ${booking.customer_id}\nProperty: ${booking.property_id}\nBooking ID: ${booking.booking_id}`,
  start: {
    dateTime: startTime,
    timeZone: 'UTC'
  },
  end: {
    dateTime: endTime,
    timeZone: 'UTC'
  },
  attendees: [
    {
      email: `${booking.customer_id}@customer.com`,
      displayName: 'Customer'
    }
  ],
  reminders: {
    useDefault: false,
    overrides: [
      { method: 'email', minutes: 1440 }, // 24 hours before
      { method: 'popup', minutes: 60 } // 1 hour before
    ]
  }
};

return {
  ...booking,
  calendar_event: calendarEvent,
  event_start: startTime,
  event_end: endTime
};

