// Schedule follow-up reminders
const booking = $input.item.json;
const visitDate = new Date(booking.date + 'T' + booking.time);
const now = new Date();

// Calculate time until visit
const hoursUntilVisit = (visitDate - now) / (1000 * 60 * 60);

let followUpSchedule = [];

if (hoursUntilVisit > 24) {
  // 24 hours before
  followUpSchedule.push({
    type: 'reminder',
    timing: '24h_before',
    scheduled_for: new Date(visitDate.getTime() - 24 * 60 * 60 * 1000).toISOString()
  });
}

if (hoursUntilVisit > 2) {
  // 2 hours before
  followUpSchedule.push({
    type: 'reminder',
    timing: '2h_before',
    scheduled_for: new Date(visitDate.getTime() - 2 * 60 * 60 * 1000).toISOString()
  });
}

// 24 hours after visit
followUpSchedule.push({
  type: 'followup',
  timing: '24h_after',
  scheduled_for: new Date(visitDate.getTime() + 24 * 60 * 60 * 1000).toISOString()
});

return {
  ...booking,
  follow_up_schedule: followUpSchedule
};
